            'file' => 'required|file',
        ]);

        $file = $request->file('file');
        $path = $file->store('', 's3'); 


        $permanentLink = Storage::disk('s3')->url($path);

        return redirect()->route('s3.index')->with('success', 'File uploaded successfully.')
                         ->with('permanentLink', $permanentLink);
    }
}
