```php
<?php
require_once __DIR__ . '/vendor/autoload.php';
use Exception;
use MongoDBClient;

$uri = getenv('MONGODB_URI');

try {
    $client = new MongoDBClient($uri, [], $options);
    $client->selectDatabase('admin')->command(['ping' => 1]);
